const test = require("node:test");
const assert = require("node:assert");

const { startServer, api } = require("./helpers");

async function expectRejected(base, url) {
  const resp = await api(base, "POST", "/api/links", { url, slug: "probe" });
  assert.strictEqual(resp.status, 400, `expected 400 for ${JSON.stringify(url)}, got ${resp.status}`);
}

test("script-scheme and non-http URLs are rejected however they are spelled", async () => {
  const { base, close } = startServer();
  try {
    await expectRejected(base, "javascript:alert(1)");
    await expectRejected(base, "JavaScript:alert(1)");
    await expectRejected(base, "JAVASCRIPT:alert(document.cookie)");
    await expectRejected(base, "  javascript:alert(1)");
    await expectRejected(base, "data:text/html,<script>alert(1)</script>");
    await expectRejected(base, "vbscript:msgbox(1)");
    await expectRejected(base, "file:///etc/passwd");
    await expectRejected(base, "not a url at all");
  } finally {
    await close();
  }
});

test("http and https links still work end to end", async () => {
  const { base, close } = startServer();
  try {
    const https = await api(base, "POST", "/api/links", {
      url: "https://example.com/safe",
      slug: "safe",
    });
    assert.strictEqual(https.status, 201);

    const http = await api(base, "POST", "/api/links", {
      url: "http://plain.example/page",
      slug: "plain",
    });
    assert.strictEqual(http.status, 201);

    const hit = await api(base, "GET", "/r/safe");
    assert.strictEqual(hit.status, 302);
    assert.strictEqual(hit.headers.get("location"), "https://example.com/safe");
  } finally {
    await close();
  }
});

